        [{"id": "serial-port-denied", "label": "Serial Port Access Blocked", "changes": {"failedNodes": ["target-vm"], "failedEdges": ["e4"]}, "root_cause": "Developer attempted to connect to interactive serial console while SerialPortAccess is disabled.", "diverted_path": "Session rejected at project boundary; audit event emitted to Security Command Center.", "blast_radius": "Direct interactive console access denied.", "recovery": "Use Google Cloud IAP TCP forwarding and OS Login instead of serial console."}],
        "Simulates organization policy violations: demonstrates an engineer attempting to create a VM with a public IP when constraints/compute.vmExternalIpAccess is enforced.",
